import React, { useCallback, useEffect, useState } from 'react';
import { apiPath } from '../config';
import { roleLabelsFor } from '../roleLabels';

function DoctorDashboard({ user }) {
  const [tokens, setTokens] = useState([]);
  const [selectedItems, setSelectedItems] = useState({});
  const [serviceRequirements, setServiceRequirements] = useState({});
  const [aiSuggestions, setAiSuggestions] = useState({});
  const [message, setMessage] = useState('');
  const roleLabels = roleLabelsFor(user.industry_type, tokens[0]?.branch_config?.industry_settings?.role_labels || {});

  const api = useCallback(async (path, options = {}) => {
    const response = await fetch(apiPath(path), {
      credentials: 'include',
      headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
      ...options
    });
    return response.json();
  }, []);

  const refresh = useCallback(async () => {
    const data = await api('/api/provider/tokens');
    if (data.success) setTokens(data.tokens);
  }, [api]);

  useEffect(() => {
    refresh();
    const interval = setInterval(refresh, 5000);
    return () => clearInterval(interval);
  }, [refresh]);

  const askAi = async (tokenId) => {
    const data = await api(`/api/provider/tokens/${tokenId}/ai-suggestion`, {
      method: 'POST',
      body: JSON.stringify({ provider_requirements: serviceRequirements[tokenId] || '' })
    });
    if (data.success) {
      setAiSuggestions({ ...aiSuggestions, [tokenId]: data.suggestion });
      refresh();
    }
  };

  const pauseBranchQueue = async (branchId, pause) => {
    const reason = pause ? window.prompt('Enter the reason for pausing this queue') : '';
    if (pause && !reason?.trim()) return;
    const data = await api(`/api/branch/${branchId}/queue-pause`, {
      method: 'POST',
      body: JSON.stringify({ action: pause ? 'pause' : 'resume', reason })
    });
    if (data.success) {
      setMessage(pause ? 'Queue paused and users notified.' : 'Queue resumed and users notified.');
      refresh();
    } else {
      setMessage(data.error || 'Queue pause update failed.');
    }
  };

  const toggleItem = (tokenId, item) => {
    const current = selectedItems[tokenId] || [];
    const exists = current.some((entry) => entry.name === item.name);
    setSelectedItems({
      ...selectedItems,
      [tokenId]: exists ? current.filter((entry) => entry.name !== item.name) : [...current, item]
    });
  };

  const complete = async (tokenId) => {
    const providerText = (serviceRequirements[tokenId] || '').trim();
    const aiText = (aiSuggestions[tokenId] || '').trim();
    const finalSuggestion = [providerText, aiText && `AI suggestion: ${aiText}`]
      .filter(Boolean)
      .join('\n\n');
    const data = await api(`/api/provider/tokens/${tokenId}/suggestion`, {
      method: 'POST',
      body: JSON.stringify({
        suggestion_text: finalSuggestion || 'Service completed.',
        selected_items: selectedItems[tokenId] || []
      })
    });
    if (data.success) {
      setMessage(`Completed with total ${data.suggestion.aggregates.total}.`);
      refresh();
    }
  };

  const itemOptions = (token) => {
    const configured = token.branch_config?.service_provider?.search_items;
    return configured && configured.length
      ? configured
      : [
        { name: 'Consultation', price: 300 },
        { name: 'Service Charge', price: 100 },
        { name: 'Follow Up', price: 0 }
      ];
  };

  return (
    <div className="dashboard doctor-dashboard">
      <div className="dashboard-header">
        <div>
          <h1>{roleLabels.service_provider} Dashboard</h1>
          <p className="user-email">{user.name} - {user.industry_name || roleLabels.service_provider}</p>
        </div>
        <div className="stats-summary">
          <span className="stat">Active: {tokens.length}</span>
        </div>
      </div>

      {message && <div className="success-message">{message}</div>}

      <div className="patient-grid">
        {tokens.map((token) => {
          const checked = selectedItems[token.token_id] || [];
          const prices = checked.map((item) => Number(item.price || 0));
          const total = prices.reduce((sum, price) => sum + price, 0);
          const average = prices.length ? total / prices.length : 0;
          return (
            <div className="patient-card current" key={token.token_id}>
              <div className="patient-header">
                <span className="token-badge">{token.token_code}</span>
                <h4>{token.display_name || token.user_name}</h4>
                {token.emergency_accepted && <span className="badge badge-danger">Emergency</span>}
                {token.queue_paused && <span className="badge badge-warning">Paused</span>}
              </div>
              <p>{token.branch_name}</p>
              <div className="branch-control-row">
                {token.queue_paused ? (
                  <button type="button" onClick={() => pauseBranchQueue(token.branch_id, false)}>Resume Queue</button>
                ) : (
                  <button type="button" className="warning-btn" onClick={() => pauseBranchQueue(token.branch_id, true)}>Pause Queue</button>
                )}
                {token.queue_paused && <small>Reason: {token.queue_pause_reason || 'Paused by staff'}</small>}
              </div>
              <div className="details-list">
                {Object.entries(token.details || {}).map(([key, value]) => (
                  <span key={key}><strong>{key}:</strong> {String(value)}</span>
                ))}
              </div>

              <div className="provider-note-panel">
                <label htmlFor={`requirements-${token.token_id}`}>{roleLabels.service_provider} requirements</label>
                <textarea
                  id={`requirements-${token.token_id}`}
                  rows="4"
                  value={serviceRequirements[token.token_id] || ''}
                  onChange={(event) => setServiceRequirements({ ...serviceRequirements, [token.token_id]: event.target.value })}
                  placeholder="Type service requirements, notes, prescription, next step, or instruction"
                />
                <button type="button" onClick={() => askAi(token.token_id)}>Ask AI Suggestion</button>
                {(aiSuggestions[token.token_id] || token.ai_suggestion) && (
                  <div className="ai-suggestion-output">
                    <strong>AI Suggestion</strong>
                    <p>{aiSuggestions[token.token_id] || token.ai_suggestion}</p>
                  </div>
                )}
              </div>

              <div className="checkbox-list">
                {itemOptions(token).map((item) => (
                  <label key={item.name}>
                    <input
                      type="checkbox"
                      checked={checked.some((entry) => entry.name === item.name)}
                      onChange={() => toggleItem(token.token_id, item)}
                    />
                    {item.name} ({item.price})
                  </label>
                ))}
              </div>

              <div className="aggregation-bar">
                <span>Total: {total}</span>
                <span>Average: {average.toFixed(2)}</span>
                <span>Count: {checked.length}</span>
              </div>

              <button className="complete-btn" onClick={() => complete(token.token_id)}>Complete Service</button>
            </div>
          );
        })}
        {tokens.length === 0 && <p className="no-patients">No active tokens for service.</p>}
      </div>
    </div>
  );
}

export default DoctorDashboard;
